<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { getActivityCategories, getActivityById } from '../api/activity'
import { getTicketsByActivity } from '../api/ticket'
import { seckillTicket } from '../api/reservation'
import { getBlogsByActivity } from '../api/blog'
import { getActivityImage, imageFallback } from '../config/activityImages'
import { useUserStore } from '../stores/user'
import PageContainer from '../components/common/PageContainer.vue'
import PageLoading from '../components/common/PageLoading.vue'
import ErrorState from '../components/common/ErrorState.vue'
import EmptyState from '../components/common/EmptyState.vue'
import TicketCard from '../components/business/TicketCard.vue'
import BlogCard from '../components/business/BlogCard.vue'

const route=useRoute(); const router=useRouter(); const userStore=useUserStore(); const activity=ref(null); const tickets=ref([]); const blogs=ref([]); const categories=ref([]); const loading=ref(true); const error=ref(false); const dialogOpen=ref(false); const selectedTicket=ref(null); const reservedTicketIds=ref(new Set()); const submitting=ref(false)
const categoryName=computed(()=>categories.value.find(item=>item.id===activity.value?.categoryId)?.name || '城市活动'); const activityImage=computed(()=>getActivityImage(activity.value)); const price=computed(()=>activity.value?.avgPrice ? `¥${(activity.value.avgPrice/100).toFixed(0)} 起` : '免费参与')
function normalizeReservationError(message) { if (/只能预约一次|已经预约/.test(message)) return '你已经预约过这个活动'; if (/售罄|库存|名额/.test(message)) return '很遗憾，本场活动名额已满'; return message || '预约未完成，请稍后再试' }
async function loadDetail(){ loading.value=true; error.value=false; blogs.value=[]; try { const id=route.params.id; const [activityData,ticketData,categoryData]=await Promise.all([getActivityById(id),getTicketsByActivity(id),getActivityCategories()]); activity.value=activityData; tickets.value=ticketData||[]; categories.value=categoryData||[]; try { blogs.value=((await getBlogsByActivity({activityId:id,current:1}))||[]).slice(0,3) } catch { blogs.value=[] } } catch { error.value=true } finally { loading.value=false } }
function requestReservation(ticket){ if(!userStore.isLoggedIn){ router.push({name:'login',query:{redirect:route.fullPath}}); return } selectedTicket.value=ticket; dialogOpen.value=true }
async function confirmReservation(){ if(!selectedTicket.value) return; submitting.value=true; try { const orderId=await seckillTicket(selectedTicket.value.id); reservedTicketIds.value=new Set([...reservedTicketIds.value,selectedTicket.value.id]); dialogOpen.value=false; ElMessage.success(orderId ? `预约成功，订单号 ${orderId}` : '预约成功') } catch(error) { ElMessage.error(normalizeReservationError(error.message)) } finally { submitting.value=false } }
watch(()=>route.params.id,loadDetail); onMounted(loadDetail)
</script>

<template><PageContainer><PageLoading v-if="loading" /><ErrorState v-else-if="error" message="没有找到这场活动，或活动信息暂时无法加载。" @retry="loadDetail" /><template v-else-if="activity"><nav class="breadcrumb"><RouterLink to="/activities">发现活动</RouterLink><span>/</span><span>{{ activity.title }}</span></nav><img class="detail-hero" :src="activityImage" :alt="activity.title" @error="imageFallback" /><div class="title-block"><span class="category-tag">{{ categoryName }}</span><h1>{{ activity.title }}</h1><p>{{ activity.openHours || '活动时间待公布' }} · {{ activity.area || '城市活动' }}</p></div><div class="detail-layout"><div class="detail-content"><section><h2>活动信息</h2><div class="meta-grid"><div><span>时间</span><strong>{{ activity.openHours || '以活动通知为准' }}</strong></div><div><span>地点</span><strong>{{ [activity.area,activity.address].filter(Boolean).join(' · ') || '地点待公布' }}</strong></div><div><span>参考价格</span><strong>{{ price }}</strong></div></div></section><section><h2>关于这场活动</h2><p class="detail-copy">{{ activity.title }}邀你在城市里留出一点不赶路的时间。活动的具体安排、参与规则和到场提醒，请以预约凭证与现场通知为准。</p></section><section class="blog-preview"><div class="section-heading"><div><p class="eyebrow">City voices</p><h2>参加过的人怎么说</h2></div><RouterLink to="/community">去社区 →</RouterLink></div><div v-if="blogs.length" class="blog-list"><BlogCard v-for="blog in blogs" :key="blog.id" :blog="blog" :activities="{ [activity.id]: activity }" read-only /></div><EmptyState v-else title="还没有人分享体验" description="成为第一个分享活动体验的人。"><el-button plain @click="router.push('/community')">去社区</el-button></EmptyState></section></div><aside class="ticket-panel"><div class="ticket-panel-inner"><p class="eyebrow">Reservation</p><h2>选择预约凭证</h2><div v-if="tickets.length" class="ticket-list"><TicketCard v-for="ticket in tickets" :key="ticket.id" :ticket="ticket" :reserved="reservedTicketIds.has(ticket.id)" @reserve="requestReservation" /></div><EmptyState v-else title="当前活动暂无可预约名额" description="可以先收藏活动，留意后续开放信息。" /></div></aside></div></template></PageContainer><el-dialog v-model="dialogOpen" width="min(92vw, 440px)" title="确认预约"><div v-if="selectedTicket" class="confirm-info"><span>{{ categoryName }}</span><h3>{{ activity?.title }}</h3><p>{{ selectedTicket.title }}</p><strong>{{ selectedTicket.actualValue ? `¥${(selectedTicket.actualValue/100).toFixed(0)}` : '免费预约' }}</strong></div><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="submitting" @click="confirmReservation">确认预约</el-button></template></el-dialog></template>

<style scoped>.breadcrumb { display:flex; gap:var(--space-2); margin-bottom:var(--space-4); overflow:hidden; color:var(--color-text-muted); font-size:.85rem; white-space:nowrap; }.breadcrumb a { color:var(--color-primary); }.detail-hero { display:block; width:100%; aspect-ratio:16/7; border-radius:var(--radius-xl); object-fit:cover; background:var(--color-surface-muted); }.title-block { padding:var(--space-6) 0; border-bottom:1px solid var(--color-border); }.category-tag { display:inline-block; padding:4px 9px; border-radius:999px; color:var(--color-primary); background:var(--color-primary-soft); font-size:.78rem; font-weight:700; }.title-block h1 { margin:var(--space-3) 0 var(--space-2); font-family:Georgia,"Songti SC",serif; font-size:clamp(2.25rem,4vw,4rem); line-height:1.04; letter-spacing:-.065em; }.title-block p { margin:0; color:var(--color-text-secondary); }.detail-layout { display:grid; grid-template-columns:minmax(0,2fr) minmax(290px,1fr); gap:var(--space-7); padding-top:var(--space-7); }.detail-content section { padding-bottom:var(--space-7); }.detail-content h2,.ticket-panel h2 { margin:0 0 var(--space-4); font-size:1.35rem; }.meta-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:var(--space-3); }.meta-grid div { display:flex; flex-direction:column; gap:var(--space-2); padding:var(--space-4); border:1px solid var(--color-border); border-radius:var(--radius-md); background:var(--color-surface); }.meta-grid span { color:var(--color-text-muted); font-size:.78rem; }.meta-grid strong { font-size:.9rem; }.detail-copy { max-width:710px; color:var(--color-text-secondary); line-height:1.8; }.ticket-panel-inner { position:sticky; top:94px; padding:var(--space-5); border:1px solid var(--color-border); border-radius:var(--radius-lg); background:var(--color-surface-muted); }.ticket-list { display:grid; gap:var(--space-3); }.section-heading { display:flex; align-items:end; justify-content:space-between; gap:var(--space-4); }.section-heading h2 { margin:var(--space-2) 0 0; }.section-heading a { color:var(--color-primary); font-weight:700; }.blog-list { display:grid; gap:var(--space-3); margin-top:var(--space-4); }.blog-item { display:flex; gap:var(--space-3); padding:var(--space-4); border:1px solid var(--color-border); border-radius:var(--radius-md); background:var(--color-surface); }.blog-item h3 { margin:4px 0; font-size:1rem; }.blog-item p { display:-webkit-box; margin:0; overflow:hidden; color:var(--color-text-secondary); font-size:.88rem; -webkit-box-orient:vertical; -webkit-line-clamp:2; }.blog-item small { display:block; margin-top:var(--space-2); color:var(--color-text-muted); }.confirm-info { padding:var(--space-3) 0; }.confirm-info span { color:var(--color-primary); font-size:.8rem; }.confirm-info h3 { margin:var(--space-2) 0; font-size:1.25rem; }.confirm-info p { margin:0 0 var(--space-3); color:var(--color-text-secondary); }.confirm-info strong { color:var(--color-accent); font-size:1.15rem; }@media(max-width:1023px){.detail-layout{grid-template-columns:1fr}.ticket-panel-inner{position:static}.ticket-panel{order:-1}}@media(max-width:767px){.detail-hero{aspect-ratio:16/10}.title-block{padding:var(--space-5) 0}.detail-layout{gap:var(--space-6);padding-top:var(--space-6)}.meta-grid{grid-template-columns:1fr}.ticket-panel-inner{padding:var(--space-4)}.detail-content section{padding-bottom:var(--space-6)}} </style>
